examples.code:
// Accidentally public: no condition restricts who "*" actually is
{
  "Version": "2012-10-17",
  "Statement": [{
    "Sid": "AllowPartnerRead",
    "Effect": "Allow",
    "Principal": "*",
    "Action": "s3:GetObject",
    "Resource": "arn:aws:s3:::partner-exports-bucket/*"
  }]
}

// Fixed: scoped to one specific AWS account instead of the entire internet
{
  "Version": "2012-10-17",
  "Statement": [{
    "Sid": "AllowPartnerRead",
    "Effect": "Allow",
    "Principal": { "AWS": "arn:aws:iam::111122223333:root" },
    "Action": "s3:GetObject",
    "Resource": "arn:aws:s3:::partner-exports-bucket/*"
  }]
}

